def min_cost_to_paint(n, m, rectangles):
    # Initialize a set to store unique cells that need to be painted
    unique_cells = set()

    # Add all cells in the given rectangles to the set
    for x1, y1, x2, y2 in rectangles:
        for x in range(x1 - 1, x2):
            for y in range(y1 - 1, y2):
                unique_cells.add((x, y))

    # Calculate the minimum cost to paint all unique cells
    min_cost = float('inf')
    for x1 in range(1, n + 1):
        for y1 in range(1, n + 1):
            for x2 in range(x1, n + 1):
                for y2 in range(y1, n + 1):
                    if all((x, y) in unique_cells for x in range(x1 - 1, x2) for y in range(y1 - 1, y2)):
                        cost = min(x2 - x1 + 1, y2 - y1 + 1)
                        min_cost = min(min_cost, cost)

    return min_cost

# Example usage:
if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    rectangles = []
    index = 2
    for _ in range(m):
        x1 = int(data[index])
        y1 = int(data[index + 1])
        x2 = int(data[index + 2])
        y2 = int(data[index + 3])
        rectangles.append((x1, y1, x2, y2))
        index += 4

    result = min_cost_to_paint(n, m, rectangles)
    print(result)
